import Foundation

/// Original synthetic ramps, extrema, stereo separation, and a partial final
/// ALAC packet. No source-game media is included in these fixtures.
/// Source generator: scripts/assets/generate_alac_validation_fixtures.py.
enum ArenaALACStorageFixtures {
    private static let compressed: [String: String] = [
        "22050_1": "",
        "44100_1": "",
        "44100_2": "",
        "48000_1": "",
        "48000_2": ""
    ]

    static func write(rate: Int, channels: Int, directory: URL) throws -> (wav: URL, alac: URL) {
        let key = "\(rate)_\(channels)"
        guard let text = compressed[key], let alac = Data(base64Encoded: text) else { throw CocoaError(.fileReadCorruptFile) }
        var pcm = Data()
        func append<T: FixedWidthInteger>(_ value: T, to data: inout Data) {
            var little = value.littleEndian
            withUnsafeBytes(of: &little) { data.append(contentsOf: $0) }
        }
        for frame in 0..<5_003 {
            for channel in 0..<channels {
                var sample = ((frame * (97 + channel * 16) + channel * 12_345) % 65_536) - 32_768
                if frame == 0 { sample = -32_768 + channel }
                else if frame == 1 { sample = 32_767 - channel }
                else if frame == 5_002 { sample = channel == 0 ? 12_345 : -12_345 }
                append(Int16(sample), to: &pcm)
            }
        }
        var wav = Data("RIFF".utf8)
        append(UInt32(36 + pcm.count), to: &wav)
        wav.append(Data("WAVEfmt ".utf8))
        append(UInt32(16), to: &wav)
        append(UInt16(1), to: &wav)
        append(UInt16(channels), to: &wav)
        append(UInt32(rate), to: &wav)
        append(UInt32(rate * channels * 2), to: &wav)
        append(UInt16(channels * 2), to: &wav)
        append(UInt16(16), to: &wav)
        wav.append(Data("data".utf8))
        append(UInt32(pcm.count), to: &wav)
        wav.append(pcm)
        let wavURL = directory.appendingPathComponent(key + ".wav")
        let alacURL = directory.appendingPathComponent(key + ".m4a")
        try wav.write(to: wavURL)
        try alac.write(to: alacURL)
        return (wavURL, alacURL)
    }
}
